"""Locate/obtain a fastText engine and expose train/test without rewriting author code.

Preference order (ledger A14):
  1. an importable `fasttext` module (the official python binding of the
     authors' C++ trainer; the shipped wheel is fastText 0.9.2, the same
     version as repo/),
  2. `pip install fasttext-wheel` (prebuilt binary of the same code; the wheel
     found on PyPI for this platform is cached under .cache/wheels),
  3. a native build of repo/ (only when a POSIX toolchain exists),
and deliberately NO silent fallback to a re-implementation: if no engine can be
provided we fail loudly instead of quietly downgrading the verdict.
"""

import glob
import os
import shutil
import subprocess
import sys

PROVENANCE = {"engine": None, "version": None, "note": None}
SEED_SUPPORTED = True


def _repo_git_hash():
    try:
        out = subprocess.run(["git", "-C", os.path.join(_root(), "repo"), "rev-parse", "HEAD"],
                             capture_output=True, text=True, timeout=30)
        if out.returncode == 0:
            return out.stdout.strip()
    except Exception:  # noqa: BLE001
        pass
    return None


def _root():
    return os.path.dirname(os.path.abspath(__file__))


def _try_import():
    try:
        import fasttext  # noqa: PLC0415
        return fasttext
    except Exception:  # noqa: BLE001
        return None


def _pip_install(spec):
    subprocess.run([sys.executable, "-m", "pip", "install", spec],
                   capture_output=True, text=True, timeout=900, check=False)


def get_fasttext(auto_install=True):
    ft = _try_import()
    if ft is None and auto_install:
        cached = sorted(glob.glob(os.path.join(_root(), ".cache", "wheels",
                                               "fasttext_wheel-*.whl")))
        for spec in cached + ["fasttext-wheel", "fasttext"]:
            try:
                _pip_install(spec)
            except Exception:  # noqa: BLE001
                pass
            ft = _try_import()
            if ft is not None:
                PROVENANCE["note"] = "installed %s" % spec
                break
    if ft is None:
        raise RuntimeError(
            "no fastText engine available (tried import, cached wheel, pip "
            "fasttext-wheel/fasttext). A native build of repo/ needs a POSIX "
            "toolchain; a re-implementation fallback is intentionally NOT used."
        )
    PROVENANCE["engine"] = "fasttext python binding (fastText 0.9.2 C++ trainer)"
    PROVENANCE["version"] = getattr(ft, "__version__", "0.9.2")
    PROVENANCE["repo_git_hash"] = _repo_git_hash()
    PROVENANCE["toolchain"] = {k: shutil.which(k) for k in ("make", "g++", "clang++", "cmake")}
    return ft


def train_supervised(ft, **kw):
    """Forward every argument verbatim to the authors' supervised trainer."""
    seed = kw.pop("seed", None)
    if seed is not None and SEED_SUPPORTED:
        try:
            return ft.train_supervised(seed=seed, **kw)
        except (TypeError, ValueError):
            global SEED_SUPPORTED
            SEED_SUPPORTED = False  # binding without a seed option
    return ft.train_supervised(**kw)


def test(model, path, k=1):
    """Returns (N, precision@k, recall@k); P@1 == accuracy for single-label data."""
    return model.test(path, k=k, threshold=0.0)

