def feature_stats(sample_lines):
    """Vocabulary size and distinct bigram count on a sample of the training set,
    to sanity-check the feature space against the 10M-bucket hashing space."""
    vocab, bigrams = set(), set()
    for line in sample_lines:
        toks = line.split(" ")[1:]
        vocab.update(toks)
        bigrams.update(zip(toks, toks[1:]))
    return {
        "sample_lines": len(sample_lines),
        "vocab_size": len(vocab),
        "distinct_bigrams": len(bigrams),
        "bucket": config.BUCKET,
        "bin_space_probed_by_bigrams": len(bigrams) / float(config.BUCKET),
    }


